// Supabase client — NOT generated by Figma Make, safe from re-exports.
import { createClient, type SupabaseClient } from "@supabase/supabase-js";

const url = import.meta.env.VITE_SUPABASE_URL ?? "";
const key = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? "";

/** null when the env vars are missing; every caller must handle that and fall back to local data. */
export const supabase: SupabaseClient | null =
  url && key
    ? createClient(url, key, {
        auth: { persistSession: true, autoRefreshToken: true, storageKey: "study-hopper-auth" },
      })
    : null;

export const hasSupabase = supabase !== null;
